const body = $input.first().json.body;
if (!body.product_name || !body.data_points) return [{ json: { valid: false, error: 'Missing product_name or data_points' } }];
if (!Array.isArray(body.data_points) || body.data_points.length === 0) return [{ json: { valid: false, error: 'data_points must be a non-empty array' } }];
const placements = ['hero_banner','pricing_page','checkout','footer','popup','email_signature','sidebar'];
const placement = placements.includes(body.placement) ? body.placement : 'hero_banner';
return [{ json: { valid: true, productName: body.product_name.trim(), dataPoints: body.data_points.slice(0,10), placement, tone: body.tone||'confident', targetAudience: body.target_audience||'', variantCount: Math.min(5, Math.max(1, parseInt(body.variant_count)||3)), replyEmail: body.reply_email||null } }];

values.content:
Generate social proof copy.

Product: {{ $json.productName }}
Placement: {{ $json.placement.replace(/_/g,' ') }}
Tone: {{ $json.tone }}
Target audience: {{ $json.targetAudience || 'general' }}
Variants needed: {{ $json.variantCount }}

Available data points (use only these, do not invent numbers):
{{ $json.dataPoints.map((d,i) => (i+1)+'. '+d).join('\n') }}

Return this JSON:
{
  "variants": [
    {
      "text": "the social proof copy",
      "character_count": 0,
      "data_point_used": "which data point this is based on",
      "why_this_works": "one sentence"
    }
  ],
  "placement_notes": "sizing/format guidance specific to this placement type",
  "recommended_variant": 1
}

