const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let copy;
try { copy = JSON.parse(raw.replace(/```json|```/g,'').trim()); } catch(e) { return [{ json: { error: 'Parse error', raw } }]; }
const input = $('Validate Input').first().json;
copy._meta = { productName: input.productName, placement: input.placement, replyEmail: input.replyEmail };
return [{ json: copy }];

const c = $input.first().json;
const m = c._meta;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const variantBlocks = (c.variants||[]).map((v,i) => `<div style="border:2px solid ${i+1===c.recommended_variant?'#16a34a':'#e5e7eb'};border-radius:8px;padding:16px 18px;margin-bottom:12px;background:${i+1===c.recommended_variant?'#f0fdf4':'#fff'}"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px"><span style="font-size:11px;font-weight:700;color:#9ca3af">VARIANT ${i+1}${i+1===c.recommended_variant?' · RECOMMENDED':''}</span><span style="font-size:11px;color:#9ca3af">${v.character_count||v.text.length} chars</span></div><div style="font-size:18px;font-weight:700;color:#1a1a1a;margin-bottom:8px">${esc(v.text)}</div><div style="font-size:12px;color:#6b7280">${esc(v.why_this_works)}</div></div>`).join('');
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"></head><body style="margin:0;padding:16px;background:#f9fafb;font-family:sans-serif"><div style="max-width:600px;margin:0 auto"><div style="background:#111827;color:#fff;padding:18px 24px;border-radius:10px 10px 0 0"><div style="font-size:11px;text-transform:uppercase;color:#6b7280">Social Proof Copy · ${esc(m.placement.replace(/_/g,' '))}</div><div style="font-size:18px;font-weight:700">${esc(m.productName)}</div></div><div style="background:#fff;padding:18px 24px;border:1px solid #e5e7eb;border-top:none">${variantBlocks}</div><div style="background:#eff6ff;padding:14px 24px;border:1px solid #bfdbfe"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#1d4ed8;margin-bottom:5px">Placement notes</div><div style="font-size:13px;color:#1e40af">${esc(c.placement_notes)}</div></div></div></body></html>`;
return [{ json: { html, replyEmail: m.replyEmail, productName: m.productName, copy: c } }];
